'use strict';

// detox is resolved from process.cwd() (the customer's install), not the SDK package.
const path = require('path');

const detoxRoot = path.dirname(require.resolve('detox/package.json', {paths: [process.cwd()]}));
const IosExpect = require(path.join(detoxRoot, 'src/ios/expectTwo'));
const DetoxRuntimeError = require(path.join(detoxRoot, 'src/errors/DetoxRuntimeError'));

// Stock detox reaches system alerts and secured web views through XCUITest on the local Mac.
// Every other matcher, action and expectation rides the invocation channel to the app.
const cloudXcuitestRunner = {
  async execute() {
    throw new DetoxRuntimeError({
      message: 'system.element() and secured web view elements are not supported on BrowserStack iOS simulators.'
    });
  }
};

class CloudIosExpect extends IosExpect {
  constructor({invocationManager, eventEmitter}) {
    super({invocationManager, xcuitestRunner: cloudXcuitestRunner, emitter: eventEmitter});
  }
}

module.exports = CloudIosExpect;
